CREATE TABLE rule_animal_skill_operation_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id));
CREATE TABLE rule_animal_skill_operation(rule_id bigint NOT NULL REFERENCES rule_animal_skill_operation_mechanic(rule_id),operation_code text NOT NULL CHECK(operation_code IN('grow-crops','harvest-crops','raise-animals','hydroponic-farming','clone-harvesting','maneuver-riding-animal','routine-riding-care','emergency-animal-care','short-term-animal-care','long-term-animal-care','treat-animal-disease','treat-animal-poison','treat-animal-injury')),operation_domain text NOT NULL CHECK(operation_domain IN('farming','riding','veterinary')),skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),animal_subject_required boolean NOT NULL,high_technology_required boolean NOT NULL,display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,operation_code),UNIQUE(rule_id,display_order));
COMMENT ON TABLE rule_animal_skill_operation IS 'CE-SKILL-019 paired-source Farming, Riding, and Veterinary Medicine operation boundaries.';
